/* Personal inbox, generic Web Push, and user-initiated system dialer handoff. */
(()=>{
let data=null,poll=null;
const dialog=document.createElement('dialog');dialog.id='message-center';dialog.setAttribute('aria-labelledby','messages-title');dialog.style.cssText='width:min(980px,calc(100% - 24px));max-height:90dvh;border:1px solid #d2e0dc;border-radius:18px;padding:clamp(16px,3vw,30px);color:#102e38;box-sizing:border-box';document.body.append(dialog);
const button=document.createElement('button');button.className='btn';button.textContent='Messages';button.onclick=open;document.querySelector('.top').append(button);
async function api(path,method='GET',body){const r=await fetch('/api/messages/'+path,{method,cache:'no-store',headers:method==='GET'?{}:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});let v;try{v=await r.json()}catch{throw Error('Messaging service unavailable. Check your connection.')}if(!r.ok)throw Error(v.error||'Messaging request failed');return v}
const error=t=>{const el=dialog.querySelector('#msg-status');if(el)el.textContent=t};
async function badge(){try{const r=await api('summary');button.textContent=r.unread?'Messages · '+r.unread+' unread':'Messages'}catch{button.textContent='Messages'}}
async function open(){if(!dialog.open)dialog.showModal();dialog.innerHTML='<h2 id="messages-title">Messages & calls</h2><p>Loading your inbox…</p><button class="btn" id="msg-close">Close</button>';dialog.querySelector('button').onclick=()=>dialog.close();try{data=await api('inbox');draw();badge()}catch(e){dialog.innerHTML=`<h2 id="messages-title">Messages & calls</h2><p role="alert">${esc(e.message)}</p><button class="btn" id="msg-account">My account</button> <button class="btn" id="msg-close">Close</button>`;dialog.querySelector('#msg-account').onclick=()=>{dialog.close();fnAccount.load()};dialog.querySelector('#msg-close').onclick=()=>dialog.close()}}
function draw(){dialog.innerHTML=`<div class="sectiontitle"><div><h2 id="messages-title">Messages & calls</h2><p>Personal inbox · latest 100 messages · refresh to load new arrivals</p></div><button class="btn" id="msg-close">Close</button></div><div class="notice">Messages are for training coordination. This is not an emergency response channel. Push acceptance does not prove delivery or reading.</div><div class="actions" style="margin:16px 0"><button class="btn" id="msg-refresh">Refresh inbox</button><button class="btn" id="msg-push">Enable notifications on this device</button><button class="btn" id="msg-test">Send myself a test notification</button><button class="btn" id="msg-disable">Disable notifications on this device</button></div><p id="msg-status" role="status"></p><details><summary>My phone & privacy</summary><form id="msg-phone-form"><label class="field">International phone number<input name="phone" type="tel" autocomplete="tel" placeholder="+965… / +20…" value="${esc(data.profile.phone)}" maxlength="16"></label><label><input type="checkbox" name="sharePhone" ${data.profile.share_phone?'checked':''}> Share my number with approved contacts in my workspace and the application owner</label><p>Numbers are user-provided and not verified by SMS. Calling uses your device phone app and carrier plan; international charges may apply.</p><button class="btn" type="submit">Save phone preferences</button></form></details><h3>New message</h3><form id="msg-compose"><label class="field">Recipient<select name="recipient">${data.contacts.map(c=>`<option value="${c.id}">${esc(c.label)} · ${esc(c.role)}${c.id===data.me?' · me':''}</option>`).join('')}</select></label><label class="field">Subject<input name="title" required maxlength="80"></label><label class="field">Message<textarea name="body" required maxlength="2000" placeholder="Training coordination only; do not enter real patient information."></textarea></label><button class="btn primary" type="submit">Send message</button></form><h3>Inbox & sent messages</h3>${data.messages.map((m,i)=>{const incoming=m.recipient===data.me,c=data.contacts.find(c=>c.id===(incoming?m.sender:m.recipient));const accepted=data.pushStatuses.some(e=>e.message_id===m.id&&e.action==='PUSH_ACCEPTED');return `<article style="padding:16px 0;border-bottom:1px solid #dce7e3"><span class="pill ${incoming&&!m.read_at?'amber':''}">${incoming?'Received':'Sent'} · ${m.read_at?'Read':'Unread'}</span><h4 style="margin:10px 0">${esc(m.title)}</h4><p>${incoming?'From':'To'} ${esc(c?.label||'Former / unavailable contact')} · ${esc(fmt(m.created_at))}</p><p style="white-space:pre-wrap">${esc(m.body)}</p>${!incoming?`<small>Stored in recipient inbox${accepted?' · push service accepted at least one notification':''}. Reading time: ${m.read_at?esc(fmt(m.read_at)):'not recorded'}</small>`:''}${incoming&&!m.read_at?`<button class="btn" data-read="${i}">Mark as read</button>`:''}</article>`}).join('')||'<p>No messages yet.</p>'}<h3>Contact directory</h3><p>Only approved accounts permitted for your workspace appear. Phone visibility follows each contact’s sharing preference.</p>${data.contacts.map((c,i)=>`<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #dce7e3"><span><strong>${esc(c.label)}</strong> · ${esc(c.role)}<br><small>${c.phone?esc(c.phone)+' · user-provided':'Phone not shared'}</small></span>${c.phone?`<button class="btn" data-call="${i}">Call</button>`:''}</div>`).join('')}<p style="margin-top:18px">On iPhone, use the installed Home Screen app to enable Web Push. Notifications depend on device permissions and network availability. A watch requires its own delivery test.</p>`;
 dialog.querySelector('#msg-close').onclick=()=>dialog.close();dialog.querySelector('#msg-refresh').onclick=open;dialog.querySelector('#msg-push').onclick=enablePush;dialog.querySelector('#msg-disable').onclick=disablePush;dialog.querySelector('#msg-test').onclick=async()=>{try{const r=await api('test-push','POST',{});error(r.push.devices?`Push service accepted ${r.push.accepted} / ${r.push.devices}. Check your device; receipt is not yet verified.`:'No notification device is registered. Enable notifications first.')}catch(e){error(e.message)}};
 dialog.querySelector('#msg-phone-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('profile','POST',{phone:String(f.get('phone')).replace(/[\s()-]/g,''),sharePhone:f.has('sharePhone')});await open();error('Phone preferences saved. Number is user-provided, not SMS verified.')}catch(e){error(e.message)}};
 let requestKey=teamRequestId();dialog.querySelector('#msg-compose').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const f=Object.fromEntries(new FormData(e.target)),r=await api('send','POST',{...f,requestKey});await open();error(r.duplicate?'Message was already stored; no duplicate was sent.':`Message stored. Push service accepted ${r.push.accepted} notification(s). Recipient reading is tracked separately.`);requestKey=teamRequestId()}catch(e){error(e.message);b.disabled=false}};
 dialog.querySelectorAll('[data-read]').forEach(b=>b.onclick=async()=>{try{await api('read','POST',{id:data.messages[Number(b.dataset.read)].id});await open()}catch(e){error(e.message)}});
 dialog.querySelectorAll('[data-call]').forEach(b=>b.onclick=async()=>{try{const r=await api('dial','POST',{recipient:data.contacts[Number(b.dataset.call)].id});error('Opening the system phone app. A connected call is not verified by this application.');location.href=r.tel}catch(e){error(e.message)}});
}
function keyBytes(s){const b=atob(s.replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(b,c=>c.charCodeAt(0))}
async function enablePush(){try{if(!('Notification'in window)||!('PushManager'in window)||!('serviceWorker'in navigator))throw Error('Web Push is unavailable here. On iPhone, open the installed Home Screen app.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notifications were not enabled. Allow them in your browser / device settings if you want to receive alerts.');if(!data.pushPublicKey)throw Error('Push service is not configured.');const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();if(sub){const existingKey=sub.options.applicationServerKey;if(existingKey&&btoa(String.fromCharCode(...new Uint8Array(existingKey))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')!==data.pushPublicKey){await sub.unsubscribe();sub=null}}
 if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:keyBytes(data.pushPublicKey)});await api('subscribe','POST',sub.toJSON());error('This device is registered. Use “Send myself a test notification” to verify receipt.')}catch(e){error(e.message)}}
async function disablePush(){try{if('serviceWorker'in navigator){const reg=await navigator.serviceWorker.ready,sub=await reg.pushManager.getSubscription();if(sub){await api('unsubscribe','POST',{endpoint:sub.endpoint});await sub.unsubscribe()}}error('Notifications disabled on this device.')}catch(e){error(e.message)}}
window.fnMessages={open,reset:()=>{data=null;dialog.close();dialog.innerHTML='';button.textContent='Messages'}};setInterval(()=>{if(!document.hidden&&!dialog.open)badge()},20000);window.addEventListener('focus',badge);if(location.hash==='#messages')open();
})();
